const tileAt=(x,y)=>{if(!M||y<0||y>=M.rows.length||x<0||x>=M.rows[0].length)return null;const md=G&&G.mods&&G.mods[MK];if(md){const v=md[x+","+y];if(v)return v}return M.rows[y][x]};
