  const t=tileAt(nx,ny);if(t==="o"&&(POWER("FORZA")||knows("FORZA"))){const bx=nx+dx,by=ny+dy,bt=tileAt(bx,by);if(bt&&".:C\"".includes(bt)&&!npcAt(bx,by)){setMod(nx,ny,M.cave?"C":":");setMod(bx,by,"o");SFX.bump();const w=knows("FORZA");say(w?`${MN(w)} usa SPINTA DI FORZA: il masso si sposta!`:"Con FORZA sposti il masso!");return}}
