/* classi di allenatori: frasi e premio */const TRCL={ALLENATORE:{m:10,pre:["Ehi! Sfida!","I nostri sguardi si sono incrociati: si gioca!"],lose:["Che partita!","Devo tornare ad allenarmi."],after:["Allena bene i tuoi, come faccio io."]},TIFOSO:{m:0,pre:["FORZA RAGAZZIII! Partita!","Ho la sciarpa, il tamburo e una squadra. Giochiamo!"],lose:["Vi applaudo comunque… no, non è vero."],after:["Il tifo è una cosa seria."]},CHEERLEADER:{m:5,pre:["Pronti? Via! Sfida sfida sfida!","Un salto, un giro e… partita!"],lose:["Ok, ok, bel ritmo!"],after:["Gli applausi li faccio solo a chi vince."]},ARBITRO:{m:15,pre:["Fischio d inizio: tu contro me!","Niente falli, eh? Partita!"],lose:["Vinta regolarmente. Rispetto."],after:["Le regole sono le regole."]},GIORNALISTA:{m:20,pre:["Un articolo sulla tua sconfitta? Partita!","Domanda: resisti ai miei giocatori?"],lose:["Titolo di domani: battuto."],after:["Ti dedicherò una pagina."]},STATISTICO:{m:20,pre:["Il 73% dei miei avversari perde. Partita!","Calcolo le tue probabilità… basse."],lose:["I numeri non dicono tutto."],after:["Hai alzato la mia percentuale di sconfitte."]},ROOKIE:{m:-10,pre:["È la mia prima sfida! Sii gentile!","Rookie contro rookie? Dai!"],lose:["Wow, sei forte!"],after:["Un giorno sarò come te."]},VETERANO:{m:30,pre:["Giovane, impara qualcosa.","Ai miei tempi… vabbè, partita."],lose:["Hai il fuoco negli occhi."],after:["Il basket è di chi lo rispetta."]},MASCOTTE:{m:0,pre:["Squeak! Partita!","La mascotte non si arrende mai!"],lose:["Squeak…"],after:["Squeak squeak!"]},PREPARATORE:{m:15,pre:["Prima lo stretching, poi la sfida!","Vediamo la tua condizione fisica."],lose:["Gambe buone, davvero."],after:["Riscaldati sempre."]},"TALENT SCOUT":{m:40,pre:["Sto cercando talenti. Vediamo i tuoi.","Ti ho già messo in lista. Partita!"],lose:["Interessante. Molto interessante."],after:["Ti terrò d occhio."]},RAGAZZINO:{m:-15,pre:["Sei grande! Giochi con me?","Il mio giocatore è il più forte del mondo!"],lose:["Uffa!"],after:["La prossima volta vinco io!"]}};;
